import java.nio.*;import java.util.*;class Solution{static final int MAX=1_048_576;static byte[]frame(byte[]payload){if(payload.length>MAX)throw new IllegalArgumentException("too large");ByteBuffer buffer=ByteBuffer.allocate(4+payload.length);buffer.putInt(payload.length).put(payload);return buffer.array();}static byte[]decode(byte[]packet){if(packet.length<4)throw new IllegalArgumentException("short");ByteBuffer buffer=ByteBuffer.wrap(packet);int length=buffer.getInt();if(length<0||length>MAX||length!=buffer.remaining())throw new IllegalArgumentException("length");byte[]payload=new byte[length];buffer.get(payload);return payload;}}
